export const getIconByName = (iconName: string, isSelected: boolean): string | null => {
  if (!iconName) return null;
  const key = isSelected ? iconName : `${iconName}_Outline`;
  return ICONS[key as keyof typeof ICONS] ?? ICONS[iconName as keyof typeof ICONS] ?? null;
};
